#!/usr/bin/env node
/**
 * Builds src/tokens/generated/* from the Figma export.
 *
 *   tokens/figma-export.json  – raw export (figma-plugin/ writes it)
 *   tokens/overrides.json     – deliberate, documented deviations from Figma
 *
 * Usage:
 *   node scripts/tokens/build-tokens.mjs           write generated files
 *   node scripts/tokens/build-tokens.mjs --check   fail if generated files are stale (CI)
 */
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import * as prettier from 'prettier';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..', '..');
const EXPORT_PATH = join(ROOT, 'tokens', 'figma-export.json');
const OVERRIDES_PATH = join(ROOT, 'tokens', 'overrides.json');
const OUT_DIR = join(ROOT, 'src', 'tokens', 'generated');
const IS_CHECK = process.argv.includes('--check');

const HEADER =
  '// AUTO-GENERATED by scripts/tokens/build-tokens.mjs from tokens/figma-export.json.\n' +
  '// Do not edit by hand: change Figma (or tokens/overrides.json) and run `npm run tokens:build`.\n\n';

const FONT_WEIGHTS = {
  Thin: '100',
  'Extra Light': '200',
  ExtraLight: '200',
  Light: '300',
  Regular: '400',
  Medium: '500',
  'Semi Bold': '600',
  SemiBold: '600',
  Bold: '700',
  'Extra Bold': '800',
  ExtraBold: '800',
  Black: '900',
};

const exportJson = JSON.parse(readFileSync(EXPORT_PATH, 'utf8'));
const overrides = existsSync(OVERRIDES_PATH)
  ? JSON.parse(readFileSync(OVERRIDES_PATH, 'utf8'))
  : {};
const appliedOverrides = [];

const camelCase = value =>
  value.replace(/[-_\s]+(.)/g, (_, char) => char.toUpperCase());

const firstModeValue = variable => Object.values(variable.values)[0];

function collection(name) {
  const found = exportJson.variables[name];
  if (!found) throw new Error(`Figma export has no "${name}" collection`);
  if (found.modes.length !== 1) {
    // Theming by mode (e.g. dark) is not supported yet: components use keys, so adding it later is additive.
    console.warn(
      `"${name}" has ${found.modes.length} modes; only the first one is used.`,
    );
  }
  return found.variables;
}

// ---------- colors ----------
function buildPalette() {
  const palette = {};
  for (const [name, variable] of Object.entries(collection('Colors'))) {
    palette[camelCase(name)] = firstModeValue(variable).toUpperCase();
  }
  return palette;
}

function buildSemantic(palette) {
  const groups = {};
  for (const [name, variable] of Object.entries(collection('Semantic'))) {
    const [group, role] = name.split('/');
    const value = firstModeValue(variable);
    const ref =
      typeof value === 'object' && value.alias
        ? `palette.${camelCase(value.alias)}`
        : JSON.stringify(value);
    if (typeof value === 'object' && !(camelCase(value.alias) in palette)) {
      throw new Error(
        `Semantic "${name}" points to unknown palette color "${value.alias}"`,
      );
    }
    groups[camelCase(group)] ??= {};
    groups[camelCase(group)][camelCase(role)] = ref;
  }
  return groups;
}

// ---------- dimensions ----------
function dimensionKey(name) {
  const raw = name.split('/').pop();
  if (raw.startsWith('-')) return `neg${raw.slice(1).replace('_', '.')}`;
  return raw.replace('_', '.');
}

function buildScale(collectionName) {
  return Object.entries(collection(collectionName))
    .map(([name, variable]) => [dimensionKey(name), firstModeValue(variable)])
    .sort((a, b) => a[1] - b[1]);
}

// ---------- typography ----------
function override(kind, styleName, figmaValue) {
  const table = overrides.typography?.[kind];
  if (!table) return figmaValue;
  const value = styleName in table ? table[styleName] : table['*'];
  if (value === undefined) return figmaValue;
  // Figma AUTO values have no number to compare against, so they are fills, not drift.
  if (figmaValue !== undefined && value !== figmaValue) {
    appliedOverrides.push(
      `typography.${kind} ${styleName}: figma=${JSON.stringify(figmaValue)} -> ${JSON.stringify(value)}`,
    );
  }
  return value;
}

function buildTypography() {
  const groups = {};
  for (const [name, style] of Object.entries(exportJson.textStyles)) {
    const weight = FONT_WEIGHTS[style.fontStyle];
    if (!weight)
      throw new Error(`Unknown font style "${style.fontStyle}" in "${name}"`);
    const [group, variantRaw] = name.includes('/')
      ? name.split('/')
      : [name, style.fontStyle];
    const variant = camelCase(variantRaw.toLowerCase());

    const figmaLineHeight =
      style.lineHeight.unit === 'PIXELS' ? style.lineHeight.value : undefined;
    const figmaLetterSpacing =
      style.letterSpacing.unit === 'PIXELS'
        ? Math.round(style.letterSpacing.value * 1000) / 1000
        : 0;

    const token = {
      fontFamily: `${style.fontFamily}-${style.fontStyle.replace(/\s+/g, '')}`,
      fontWeight: weight,
      fontSize: override('fontSize', name, style.fontSize),
      lineHeight: override('lineHeight', name, figmaLineHeight),
      letterSpacing: override('letterSpacing', name, figmaLetterSpacing),
    };
    const figmaDecoration = {
      STRIKETHROUGH: 'line-through',
      UNDERLINE: 'underline',
    }[style.textDecoration];
    const decoration = override('textDecorationLine', name, figmaDecoration);
    if (decoration) token.textDecorationLine = decoration;
    if (token.lineHeight === undefined) delete token.lineHeight;

    groups[camelCase(group)] ??= {};
    groups[camelCase(group)][variant] = token;
  }
  return groups;
}

// ---------- shadows ----------
function buildShadows() {
  const shadows = {};
  for (const [name, effects] of Object.entries(exportJson.effectStyles)) {
    const key = camelCase(name.split('/').pop());
    shadows[key] = effects
      .filter(
        effect =>
          effect.type === 'DROP_SHADOW' || effect.type === 'INNER_SHADOW',
      )
      .map(effect => ({
        offsetX: effect.offset.x,
        offsetY: effect.offset.y,
        blurRadius: effect.radius,
        spreadDistance: effect.spread ?? 0,
        color: effect.color.toUpperCase(),
        ...(effect.type === 'INNER_SHADOW' ? { inset: true } : {}),
      }));
  }
  return shadows;
}

// ---------- emit ----------
const literal = value => JSON.stringify(value, null, 2);
const objectFromEntries = entries =>
  `{\n${entries.map(([k, v]) => `  ${/^[a-zA-Z_$][\w$]*$/.test(k) || /^\d+(\.\d+)?$/.test(k) ? k : JSON.stringify(k)}: ${v},`).join('\n')}\n}`;

const palette = buildPalette();
const semantic = buildSemantic(palette);
const files = {
  'palette.ts': `${HEADER}/** Raw Figma palette ("Colors" collection). Prefer semantic \`colors\` in components. */\nexport const palette = ${literal(palette)} as const;\n`,
  'colors.ts': `${HEADER}import { palette } from './palette';\n\n/** Semantic color roles ("Semantic" collection). */\nexport const colors = {\n${Object.entries(
    semantic,
  )
    .map(
      ([group, roles]) =>
        `  ${group}: ${objectFromEntries(Object.entries(roles))},`,
    )
    .join('\n')}\n} as const;\n`,
  'space.ts': `${HEADER}/** Spacing scale ("Spacing" collection): space/N, space/0_5 -> 0.5, space/-2 -> neg2. */\nexport const space = ${objectFromEntries(buildScale('Spacing').map(([k, v]) => [k, v]))} as const;\n`,
  'radius.ts': `${HEADER}/** Corner radii ("Radius" collection). */\nexport const radius = ${objectFromEntries(buildScale('Radius').map(([k, v]) => [k, v]))} as const;\n`,
  'stroke.ts': `${HEADER}/** Border widths ("Stroke" collection). */\nexport const stroke = ${objectFromEntries(buildScale('Stroke').map(([k, v]) => [k, v]))} as const;\n`,
  'typography.ts': `${HEADER}/** Text styles. Font files are bundled by the app; names follow "<Family>-<Style>". */\nexport const typography = ${literal(buildTypography())} as const;\n`,
  'shadows.ts': `${HEADER}/** Effect styles as React Native \`boxShadow\` values (New Architecture). */\nexport const shadows = ${literal(buildShadows())} as const;\n`,
  'index.ts': `${HEADER}export { colors } from './colors';\nexport { palette } from './palette';\nexport { radius } from './radius';\nexport { shadows } from './shadows';\nexport { space } from './space';\nexport { stroke } from './stroke';\nexport { typography } from './typography';\n`,
};

const prettierConfig =
  (await prettier.resolveConfig(join(OUT_DIR, 'index.ts'))) ?? {};
let staleFiles = 0;
mkdirSync(OUT_DIR, { recursive: true });
for (const [fileName, source] of Object.entries(files)) {
  const filePath = join(OUT_DIR, fileName);
  const formatted = await prettier.format(source, {
    ...prettierConfig,
    filepath: filePath,
  });
  const current = existsSync(filePath) ? readFileSync(filePath, 'utf8') : null;
  if (current === formatted) continue;
  if (IS_CHECK) {
    console.error(`Stale: src/tokens/generated/${fileName}`);
    staleFiles += 1;
  } else {
    writeFileSync(filePath, formatted);
    console.warn(`Wrote src/tokens/generated/${fileName}`);
  }
}

if (appliedOverrides.length) {
  console.warn(
    `\n${appliedOverrides.length} override(s) differ from Figma (see tokens/overrides.json):`,
  );
  for (const line of appliedOverrides) console.warn(`  - ${line}`);
}

if (staleFiles) {
  console.error(
    '\nGenerated tokens are out of date. Run `npm run tokens:build` and commit the result.',
  );
  process.exit(1);
}
